def get_array_namespace(*values):
    """Return the single non-NumPy Array API namespace used by values."""
    namespaces = set()

    def visit(value):
        if isinstance(value, (list, tuple)):
            for item in value:
                visit(item)
            return
        namespace = getattr(value, "__array_namespace__", None)
        if namespace is not None:
            namespaces.add(namespace())

    for value in values:
        visit(value)
    namespaces.discard(np)
    if len(namespaces) > 1:
        names = [getattr(namespace, "__name__", repr(namespace)) for namespace in namespaces]
        raise ValueError(f"Mixed array types {names} are not supported.")
    return next(iter(namespaces)) if namespaces else np


