def isdtype(dtype, kind, xp=None) -> bool:
    """Array-namespace aware dtype category test."""
    if xp is None or xp is np:
        kinds = kind if isinstance(kind, tuple) else (kind,)
        invalid = {value for value in kinds if not isinstance(value, str | np.dtype)}
        if invalid:
            raise TypeError(
                "kind must be a string, numpy dtype, or a tuple of these; "
                f"got {invalid}"
            )
        return npcompat.isdtype(dtype, kind)
    return xp.isdtype(dtype, kind)


