def _assert_compat_valid(compat):
    if isinstance(compat, CombineKwargDefault):
        return
    if compat not in _VALID_COMPAT:
        valid = ", ".join(repr(value) for value in _VALID_COMPAT)
        raise ValueError(f"compat={compat!r} invalid: must be one of {valid}")























































































MergeElement = tuple[Variable, Index | None]


def _assert_prioritized_valid(
    grouped: dict[Hashable, list[MergeElement]],
    prioritized: Mapping[Any, MergeElement],
) -> None:
    index_names: dict[int, set[Hashable]] = defaultdict(set)
    indexes: dict[int, Index] = {}
    for name, elements in grouped.items():
        for _, index in elements:
            if index is not None:
                index_names[id(index)].add(name)
                indexes[id(index)] = index

    prioritized_names = set(prioritized)
    for ident, names in index_names.items():
        overlap = names & prioritized_names
        if overlap and overlap != names:
            overlap_str = ", ".join(repr(name) for name in overlap)
            names_str = ", ".join(repr(name) for name in names)
            raise ValueError(
                f"cannot prioritize {overlap_str}, which would corrupt the "
                f"following index built from coordinates {names_str}:\n{indexes[ident]}"
            )


def collect_from_coordinates(
    list_of_coords: list[Coordinates],
) -> dict[Hashable, list[MergeElement]]:
    grouped: dict[Hashable, list[MergeElement]] = defaultdict(list)
    for coords in list_of_coords:
        for name, variable in coords.variables.items():
            grouped[name].append((variable, coords.xindexes.get(name)))
    return grouped


def unique_variable(
    name: Hashable,
    variables: list[Variable],
    compat: CompatOptions | CombineKwargDefault = "broadcast_equals",
    equals: bool | None = None,
) -> tuple[bool | None, Variable]:
    """Return the compatible variable represented by a group of variables."""
    _assert_compat_valid(compat)
    if not variables:
        raise ValueError("unique_variable requires at least one variable")

    compat_value = compat._value if isinstance(compat, CombineKwargDefault) else compat
    out = variables[0]
    if len(variables) == 1 or compat_value == "override":
        return equals, out

    if compat_value == "minimal":
        compat_value = "broadcast_equals"

    if compat_value == "broadcast_equals":
        dim_lengths = broadcast_dimension_size(variables)
        out = out.set_dims(dim_lengths)

    if equals is None:
        for var in variables[1:]:
            equals = getattr(out, compat_value)(
                var, equiv=duck_array_ops.lazy_array_equiv
            )
            if equals is not True:
                break

    if equals is None:
        equals = all(getattr(out, compat_value)(var) for var in variables[1:])

    if not equals:
        raise MergeError(
            f"conflicting values for variable {name!r} on objects to be combined. "
            "You can skip this check by specifying compat='override'."
        )

    if compat_value == "no_conflicts":
        for var in variables[1:]:
            out = out.fillna(var)

    return equals, out


def merge_attrs(variable_attrs, combine_attrs, context=None):
    """Combine attribute mappings according to *combine_attrs*."""
    if not variable_attrs:
        return None
    if callable(combine_attrs):
        return combine_attrs(variable_attrs, context=context)
    if combine_attrs == "drop":
        return {}
    if combine_attrs == "override":
        return dict(variable_attrs[0])
    if combine_attrs == "identical":
        if not all(
            utils.dict_equiv(variable_attrs[0], attrs, compat=equivalent_attrs)
            for attrs in variable_attrs[1:]
        ):
            raise MergeError(
                "combine_attrs='identical', but attrs differ. "
                f"First attrs: {variable_attrs[0]!r}"
            )
        return dict(variable_attrs[0])
    if combine_attrs == "no_conflicts":
        result: dict[Any, Any] = {}
        for attrs in variable_attrs:
            for key, value in attrs.items():
                if key in result and not equivalent_attrs(result[key], value):
                    raise MergeError(
                        "combine_attrs='no_conflicts', but some values are not "
                        f"the same. Merging {result!r} with {attrs!r}"
                    )
                result[key] = value
        return result
    if combine_attrs == "drop_conflicts":
        result = {}
        dropped: set[Any] = set()
        for attrs in variable_attrs:
            for key, value in attrs.items():
                if key in dropped:
                    continue
                if key in result and not equivalent_attrs(result[key], value):
                    result.pop(key)
                    dropped.add(key)
                else:
                    result[key] = value
        return result
    raise ValueError(f"Unrecognised value for combine_attrs={combine_attrs!r}")


def merge_collected(
    grouped: dict[Any, list[MergeElement]],
    prioritized: Mapping[Any, MergeElement] | None = None,
    compat: CompatOptions | CombineKwargDefault = "minimal",
    combine_attrs: CombineAttrsOptions = "override",
    equals: dict[Any, bool] | None = None,
) -> tuple[dict[Hashable, Variable], dict[Hashable, Index]]:
    """Merge groups of variables while preserving complete indexes."""
    _assert_compat_valid(compat)
    if prioritized is None:
        prioritized = {}
    _assert_prioritized_valid(grouped, prioritized)

    merged_vars: dict[Hashable, Variable] = {}
    merged_indexes: dict[Hashable, Index] = {}
    cached_equals = {} if equals is None else equals
    names = dict.fromkeys([*grouped, *prioritized])

    for name in names:
        if name in prioritized:
            variable, index = prioritized[name]
            merged_vars[name] = variable
            if index is not None:
                merged_indexes[name] = index
            continue

        elements = grouped[name]
        indexed = [(var, index) for var, index in elements if index is not None]
        if indexed:
            variable, index = indexed[0]
            assert index is not None
            for other_var, other_index in indexed[1:]:
                assert other_index is not None
                if not indexes_equal(index, other_index, variable, other_var):
                    raise MergeError(
                        f"conflicting values/indexes on objects to be combined for "
                        f"coordinate {name!r}"
                    )
            variable = variable.copy(deep=False)
            try:
                variable.attrs = merge_attrs(
                    [var.attrs for var, _ in elements], combine_attrs
                )
            except MergeError:
                if (
                    isinstance(compat, CombineKwargDefault)
                    and compat._value == compat._old
                ):
                    emit_user_level_warning(
                        compat.warning_message(
                            "Attribute conflicts may be handled differently "
                            "under the new compatibility default."
                        ),
                        FutureWarning,
                    )
                raise
            merged_vars[name] = variable
            merged_indexes[name] = index
            continue

        try:
            equal, variable = unique_variable(
                name,
                [var for var, _ in elements],
                compat=compat,
                equals=cached_equals.get(name),
            )
        except MergeError:
            if compat == "minimal":
                continue
            raise
        if (
            isinstance(compat, CombineKwargDefault)
            and compat._value == compat._old
            and len(elements) > 1
            and any(not elements[0][0].equals(var) for var, _ in elements[1:])
        ):
            emit_user_level_warning(
                compat.warning_message(
                    "The current default may combine variables that the new "
                    "default will take from the first object."
                ),
                FutureWarning,
            )
        cached_equals[name] = cast(bool, equal)
        variable = variable.copy(deep=False)
        try:
            variable.attrs = merge_attrs(
                [var.attrs for var, _ in elements], combine_attrs
            )
        except MergeError:
            if isinstance(compat, CombineKwargDefault) and compat._value == compat._old:
                emit_user_level_warning(
                    compat.warning_message(
                        "Attribute conflicts may be handled differently under "
                        "the new compatibility default."
                    ),
                    FutureWarning,
                )
            raise
        merged_vars[name] = variable

    return merged_vars, filter_indexes_from_coords(
        merged_indexes, set(merged_vars)
    )


def merge_coordinates_without_align(
    objects: list[Coordinates],
    prioritized: Mapping[Any, MergeElement] | None = None,
    exclude_dims: AbstractSet = frozenset(),
    combine_attrs: CombineAttrsOptions = "override",
) -> tuple[dict[Hashable, Variable], dict[Hashable, Index]]:
    """Merge coordinates already known to be aligned."""
    grouped = collect_from_coordinates(objects)
    if exclude_dims:
        grouped = {
            name: elements
            for name, elements in grouped.items()
            if all(exclude_dims.isdisjoint(var.dims) for var, _ in elements)
        }
        if prioritized is not None:
            prioritized = {
                name: element
                for name, element in prioritized.items()
                if exclude_dims.isdisjoint(element[0].dims)
            }
    return merge_collected(
        grouped,
        prioritized=prioritized,
        compat="minimal",
        combine_attrs=combine_attrs,
    )

