def merge_attrs(variable_attrs, combine_attrs, context=None):
    """Combine attribute mappings according to *combine_attrs*."""
    if not variable_attrs:
        return None
    if callable(combine_attrs):
        return combine_attrs(variable_attrs, context=context)
    if combine_attrs == "drop":
        return {}
    if combine_attrs == "override":
        return dict(variable_attrs[0])
    if combine_attrs == "identical":
        if not all(
            utils.dict_equiv(variable_attrs[0], attrs, compat=equivalent_attrs)
            for attrs in variable_attrs[1:]
        ):
            raise MergeError(
                "combine_attrs='identical', but attrs differ. "
                f"First attrs: {variable_attrs[0]!r}"
            )
        return dict(variable_attrs[0])
    if combine_attrs == "no_conflicts":
        result: dict[Any, Any] = {}
        for attrs in variable_attrs:
            for key, value in attrs.items():
                if key in result and not equivalent_attrs(result[key], value):
                    raise MergeError(
                        "combine_attrs='no_conflicts', but some values are not "
                        f"the same. Merging {result!r} with {attrs!r}"
                    )
                result[key] = value
        return result
    if combine_attrs == "drop_conflicts":
        result = {}
        dropped: set[Any] = set()
        for attrs in variable_attrs:
            for key, value in attrs.items():
                if key in dropped:
                    continue
                if key in result and not equivalent_attrs(result[key], value):
